API_name: search_public_restrooms
Description:
{
  "description": "Searches for public bathrooms, toilets, and restrooms worldwide. The database has over 60,000+ entries and supports searching by location and pagination.",
  "required_parameters": [],
  "optional_parameters": [
    {
      "name": "states",
      "type": "String",
      "description": "A comma-separated list of US state abbreviations to filter the search (e.g., NY,FL).",
      "default": "NY,FL"
    },
    {
      "name": "lat",
      "type": "Number",
      "description": "Latitude of the desired location for proximity search."
    },
    {
      "name": "lon",
      "type": "Number",
      "description": "Longitude of the desired location for proximity search. Must be supplied if 'lat' is used."
    },
    {
      "name": "page",
      "type": "Number",
      "description": "The page number for result pagination.",
      "default": "1"
    },
    {
      "name": "per_page",
      "type": "Number",
      "description": "The number of results to return per page.",
      "default": "10"
    }
  ]
}

