API_name: get_media_news
Description:
{
  "description": "Access current and trending news and articles related to movies, TV shows, and celebrities. Allows filtering by media category, country, and language, and supports result pagination.",
  "required_parameters": [],
  "optional_parameters": [
    {
      "name": "category",
      "type": "String",
      "description": "The type of media or topic to search for. One of the followings: TOP (Trending/General News), MOVIE, TV, CELEBRITY, UNKNOWN."
    },
    {
      "name": "first",
      "type": "Number",
      "description": "The number of news items per response for paging purpose.",
      "default": "20"
    },
    {
      "name": "after",
      "type": "String",
      "description": "Paging cursor. Leave empty to load the first page, or use the value of 'endCursor' from the previous response to load the next page."
    },
    {
      "name": "country",
      "type": "String",
      "description": "The country code. Must be used in pair with the 'language' parameter."
    },
    {
